"""Read and hash existing evidence bytes only; never execute captured code."""
import argparse, datetime, hashlib, io, json, pathlib, re, tarfile, zipfile

def digest(stream):
    h = hashlib.sha256(); n = 0
    while chunk := stream.read(2 * 1024 * 1024): h.update(chunk); n += len(chunk)
    return n, h.hexdigest()

def safe(value):
    p = pathlib.PurePosixPath(value)
    if not value or p.is_absolute() or '..' in p.parts or '\\' in value: raise ValueError('unsafe relative path')
    return p

class Parts(io.RawIOBase):
    def __init__(self, paths): self.paths = iter(paths); self.current = None
    def readable(self): return True
    def readinto(self, buf):
        while True:
            if self.current is None:
                try: self.current = next(self.paths).open('rb')
                except StopIteration: return 0
            n = self.current.readinto(buf)
            if n: return n
            self.current.close(); self.current = None
    def close(self):
        if self.current is not None: self.current.close()
        super().close()

def verify_content_packet(path, m):
    expected = {}; logical = set(); paths = []; joined = hashlib.sha256(); count = 0; duplicates = []
    for row in m['files']:
        safe(row['path'])
        if row['path'] in logical: duplicates.append(row['path'])
        logical.add(row['path'])
        if not re.fullmatch('[0-9a-f]{64}', row['sha256']) or row['blob'] != 'blobs/' + row['sha256']: raise ValueError('invalid blob map')
        prior = expected.setdefault(row['blob'], row)
        if prior['bytes'] != row['bytes']: raise ValueError('conflicting blob size')
    if len(m['files']) != m['logicalFileCount'] or len(expected) != m['uniqueBlobCount'] or sum(r['bytes'] for r in m['files']) != m['logicalBytes']: raise ValueError('logical counts differ')
    for i, row in enumerate(m['parts'], 1):
        if row['path'] != f'evidence.tar.gz.part-{i:02d}': raise ValueError('missing or reordered part')
        p = path.parent / safe(row['path'])
        h = hashlib.sha256(); n = 0
        with p.open('rb') as f:
            while chunk := f.read(2 * 1024 * 1024): h.update(chunk); joined.update(chunk); n += len(chunk)
        if p.is_symlink() or n != row['bytes'] or h.hexdigest() != row['sha256']: raise ValueError('part bytes/hash differ')
        paths.append(p); count += n
    if count != m['archiveBytes'] or joined.hexdigest() != m['archiveSHA256']: raise ValueError('joined archive differs')
    found = set(); embedded = None
    with io.BufferedReader(Parts(paths)) as stream, tarfile.open(fileobj=stream, mode='r|gz') as archive:
        for member in archive:
            if not member.isfile(): raise ValueError('non-file archive member')
            source = archive.extractfile(member)
            if member.name == 'ARCHIVE_MANIFEST.json':
                if embedded is not None or member.size > path.stat().st_size: raise ValueError('invalid embedded manifest')
                embedded = json.load(source); continue
            if member.name not in expected or member.name in found: raise ValueError('unexpected or duplicate blob')
            row = expected[member.name]; n, h = digest(source)
            if n != row['bytes'] or h != row['sha256']: raise ValueError('blob bytes/hash differ')
            found.add(member.name)
    if set(expected) != found or embedded is None: raise ValueError('archive incomplete')
    for key in ('targetProduct','layout','files','logicalFileCount','uniqueBlobCount','logicalBytes','procedureSHA256','scope'):
        if m.get(key) != embedded.get(key): raise ValueError('embedded manifest differs: '+key)
    return {'result':'failed_logical_path_conflict' if duplicates else 'bytes_verified','containerBytesVerified':True,'duplicateLogicalPaths':duplicates,'archiveBytes':count,'archiveSHA256':joined.hexdigest(),'parts':len(paths),'logicalFiles':len(m['files']),'uniqueLogicalPaths':len(logical),'uniqueBlobs':len(found),'logicalBytes':m['logicalBytes'],'materialized':False,'acceptancePassInferred':False}

def main(repo):
    root = repo / 'docs/quality/current-review'; results = []; cache = {}; rows_total = 0
    def check_file(p, row):
        if p.is_symlink() or not p.is_file(): return {'result':'not_present'}
        if p not in cache:
            with p.open('rb') as f: cache[p] = digest(f)
        n,h = cache[p]
        return {'result':'bytes_verified' if n == row.get('bytes',n) and h == row['sha256'] else 'hash_or_size_mismatch','bytes':n,'sha256':h}
    for path in sorted(root.rglob('MANIFEST.json')):
        m = json.loads(path.read_text()); rec = {'manifest':str(path.relative_to(repo)),'manifestSHA256':hashlib.sha256(path.read_bytes()).hexdigest(),'acceptancePassInferred':False}
        if m.get('layout') == 'content-addressed-blobs':
            try: rec['packet'] = verify_content_packet(path,m)
            except Exception as e: rec['packet'] = {'result':'failed','reason':str(e),'errorType':type(e).__name__}
            print(json.dumps({'manifest':rec['manifest'],'packet':rec['packet']}),flush=True)
            results.append(rec); continue
        rows = list(m.get('files',[])); rootfile = m.get('file') or m.get('archive')
        if rootfile and m.get('sha256') and m.get('bytes') is not None: rows.append({'path':rootfile,'bytes':m['bytes'],'sha256':m['sha256']})
        if isinstance(m.get('artifacts'),list): rows.extend(m['artifacts'])
        checked = []; archive_expected = {}
        for row in rows:
            if not isinstance(row,dict) or not row.get('sha256'): continue
            name = row.get('path') or row.get('file')
            if not name:
                if row.get('archiveMember'): archive_expected[row['archiveMember']] = row
                continue
            safe(name); item = {'path':name,**check_file(path.parent / name,row)}; checked.append(item)
            if item['result'] == 'not_present': archive_expected[name] = row
        rec['directFileSummary'] = {k:sum(x['result']==k for x in checked) for k in ('bytes_verified','not_present','hash_or_size_mismatch')}
        rec['directVerifiedBytes'] = sum(x.get('bytes',0) for x in checked if x['result']=='bytes_verified')
        rec['directIssues'] = [x for x in checked if x['result']!='bytes_verified']
        rec['directFiles'] = checked; rows_total += len(checked)
        archives = [p for p in path.parent.iterdir() if p.is_file() and (p.name.endswith('.tar.gz') or p.name.endswith('.zip'))]
        rec['archiveReads'] = []
        for p in sorted(archives):
            ar = {'path':p.name,'declaredContainerCheck':next((x for x in checked if x['path']==p.name),None),'matchedDeclaredMembers':0,'members':0,'bytesRead':0,'issues':[]}
            try:
                if p.name.endswith('.zip'):
                    with zipfile.ZipFile(p) as archive:
                        for member in archive.infolist():
                            if member.is_dir(): continue
                            with archive.open(member) as f: n,h = digest(f)
                            ar['members'] += 1; ar['bytesRead'] += n
                    ar['result']='crc_verified'
                else:
                    with tarfile.open(p,'r|gz') as archive:
                        for member in archive:
                            if not member.isfile(): continue
                            n,h = digest(archive.extractfile(member)); ar['members'] += 1; ar['bytesRead'] += n
                            row = archive_expected.get(member.name)
                            if row:
                                if n != row['bytes'] or h != row['sha256']: ar['issues'].append({'member':member.name,'reason':'hash_or_size_mismatch'})
                                else: ar['matchedDeclaredMembers'] += 1; archive_expected.pop(member.name)
                    ar['result']='declared_member_bytes_verified' if ar['matchedDeclaredMembers'] and not ar['issues'] else 'archive_read_verified' if not ar['issues'] else 'failed'
            except Exception as e: ar.update({'result':'failed','reason':str(e),'errorType':type(e).__name__})
            rec['archiveReads'].append(ar)
        rec['unmatchedDeclaredArchiveMembers'] = len(archive_expected)
        rec['unavailableDeclaredMembers'] = sorted(archive_expected)
        rec['archivedDirectFileRowsVerified'] = sum(x['result']=='not_present' and x['path'] not in archive_expected for x in checked)
        results.append(rec)
    delivery_path = root / 'evidence/rb10-candidate/candidate-29-final-actual-results-1/DELIVERY.json'; d = json.loads(delivery_path.read_text()); wp = pathlib.Path(d['workspaceArtifact'])
    delivery_parts = [{'path':r['path'],'expectedBytes':r['bytes'],'expectedSHA256':r['sha256'],'workspaceArtifactPresent':(wp/r['path']).is_file(),'gitEvidenceDirectoryPresent':(delivery_path.parent/r['path']).is_file()} for r in d['parts']]
    special = []
    e = json.loads((delivery_path.parent/'verification-EXECUTION.json').read_text())
    for row in e['files']:
        p=delivery_path.parent/('verification-'+row['path']);special.append({'path':str(p.relative_to(repo)),**check_file(p,row)})
    result = {'checkedAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'scope':'Evidence byte identity and availability only; no captured code executed; no product acceptance inferred','acceptancePassInferred':False,'evidenceRoot':str(root.relative_to(repo)),'manifestCount':len(results),'directRowsChecked':rows_total,'uniqueDirectFilesHashed':len(cache),'uniqueDirectBytesHashed':sum(n for n,h in cache.values()),'manifests':results,'delivery':{'path':str(delivery_path.relative_to(repo)),'sha256':hashlib.sha256(delivery_path.read_bytes()).hexdigest(),'declared':d,'workspaceDirectoryPresent':wp.is_dir(),'workspaceManifestPresent':(wp/'MANIFEST.json').is_file(),'relocationRecordPresent':pathlib.Path(d['relocationRecord']).is_file(),'parts':delivery_parts,'result':'blocked_missing_workspace_artifact' if not wp.is_dir() else 'not_verified'},'preservedVerificationFiles':special}
    return result

if __name__=='__main__':
    parser=argparse.ArgumentParser();parser.add_argument('repo',type=pathlib.Path);parser.add_argument('--output',type=pathlib.Path,required=True);a=parser.parse_args()
    out=main(a.repo);a.output.write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n');print(json.dumps({'output':str(a.output),'manifestCount':out['manifestCount'],'delivery':out['delivery']['result']}))
